   tag=b[off:off+4].decode('latin1','ignore'); cs,to,ln=struct.unpack('>III',b[off+4:off+16]); tabs[tag]=(to,ln)
 if 'gvar' not in tabs: continue
 o,l=tabs['gvar']
 if o+20>len(b): continue
 maj,minr,axis,gcoord,coordoff,glyphcnt,flags,dataoff=struct.unpack('>HHHHIHHI', b[o:o+20])
 pos=o+20; offs=[]
 try:
