    embeds+=1; fl.append('emb'); q += 2*axis
   if tidx&GX_TI_INTERMEDIATE_TUPLE:
    inter+=1; fl.append('inter'); q += 4*axis
   if fl and len(examples)<3: examples.append((gi,tds,hex(tidx),fl))
 print(p.name,'axis',axis,'glyphcnt',glyphcnt,'glyphvar',active,'maxT',maxtup,'emb',embeds,'inter',inter,'ex',examples)
